import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;
import com.sun.net.httpserver.*;
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

public class SecureApiServer {
    private static final byte[] MASTER_KEY = new byte[32];
    private static final ConcurrentHashMap<String, UserRecord> users = new ConcurrentHashMap<>();
    private static final ConcurrentHashMap<String, SessionInfo> sessions = new ConcurrentHashMap<>();
    private static final SecureRandom random = new SecureRandom();

    static { random.nextBytes(MASTER_KEY); seedUsers(); }

    record UserRecord(String username, byte[] encryptedRole, byte[] iv, byte[] authTag) {}
    record SessionInfo(String username, long expiry, int accessLevel) {}

    static void seedUsers() {
        storeUser("admin", "ROLE_ADMIN", 9);
        storeUser("user1", "ROLE_USER", 1);
    }

    static void storeUser(String username, String role, int level) {
        try {
            byte[] iv = new byte[12];
            random.nextBytes(iv);
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            GCMParameterSpec spec = new GCMParameterSpec(128, iv);
            cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(MASTER_KEY, "AES"), spec);
            cipher.updateAAD(username.getBytes(StandardCharsets.UTF_8));
            byte[] encrypted = cipher.doFinal(role.getBytes(StandardCharsets.UTF_8));
            byte[] ciphertext = Arrays.copyOfRange(encrypted, 0, encrypted.length - 16);
            byte[] authTag = Arrays.copyOfRange(encrypted, encrypted.length - 16, encrypted.length);
            users.put(username, new UserRecord(username, ciphertext, iv, authTag));
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    static String decryptRole(UserRecord record) {
        try {
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            GCMParameterSpec spec = new GCMParameterSpec(128, record.iv());
            cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(MASTER_KEY, "AES"), spec);
            cipher.updateAAD(record.username().getBytes(StandardCharsets.UTF_8));
            byte[] combined = new byte[record.encryptedRole().length + record.authTag().length];
            System.arraycopy(record.encryptedRole(), 0, combined, 0, record.encryptedRole().length);
            System.arraycopy(record.authTag(), 0, combined, record.encryptedRole().length, record.authTag().length);
            return new String(cipher.doFinal(combined), StandardCharsets.UTF_8);
        } catch (Exception e) { throw new RuntimeException("Decryption failed", e); }
    }

    static int deriveAccessLevel(String role, String username) {
        if (role.equals("ROLE_ADMIN")) return 9;
        if (role.equals("ROLE_USER")) return 1;
        return 0;
    }

    static String createSession(String username) {
        UserRecord record = users.get(username);
        if (record == null) return null;
        String role = decryptRole(record);
        int level = deriveAccessLevel(role, username);
        String token = Base64.getUrlEncoder().encodeToString(randomBytes(24));
        sessions.put(token, new SessionInfo(username, System.currentTimeMillis() + 3600000, level));
        return token;
    }

    static byte[] randomBytes(int n) { byte[] b = new byte[n]; random.nextBytes(b); return b; }

    static boolean promoteUser(String token, String targetUser) {
        SessionInfo session = sessions.get(token);
        if (session == null || System.currentTimeMillis() > session.expiry()) return false;
        if (session.accessLevel() < 9) return false;
        UserRecord target = users.get(targetUser);
        if (target == null) return false;
        storeUser(targetUser, "ROLE_ADMIN", 9);
        refreshActiveSessions(targetUser);
        return true;
    }

    static void refreshActiveSessions(String username) {
        UserRecord record = users.get(username);
        String newRole = decryptRole(record);
        int newLevel = deriveAccessLevel(newRole, username);
        sessions.forEach((tok, info) -> {
            if (info.username().equals(username)) {
                sessions.put(tok, new SessionInfo(username, info.expiry(), newLevel));
            }
        });
    }

    static boolean registerUser(String username, String desiredRole) {
        if (users.containsKey(username)) return false;
        String sanitizedRole = sanitizeRole(desiredRole);
        storeUser(username, sanitizedRole, deriveAccessLevel(sanitizedRole, username));
        return true;
    }

    static String sanitizeRole(String input) {
        String normalized = input.trim().toUpperCase();
        if (normalized.equals("ROLE_ADMIN") || normalized.equals("ROLE_USER")) {
            return "ROLE_USER";
        }
        return "ROLE_USER";
    }

    static boolean updateProfile(String token, String newDisplayName) {
        SessionInfo session = sessions.get(token);
        if (session == null || System.currentTimeMillis() > session.expiry()) return false;
        String username = session.username();
        UserRecord current = users.get(username);
        if (current == null) return false;
        // Profile update stores display name but preserves role encryption
        // Re-encrypt with new AAD that includes display name for binding
        String currentRole = decryptRole(current);
        reEncryptWithBinding(username, currentRole, newDisplayName);
        return true;
    }

    static void reEncryptWithBinding(String username, String role, String displayName) {
        try {
            byte[] iv = new byte[12];
            random.nextBytes(iv);
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            GCMParameterSpec spec = new GCMParameterSpec(128, iv);
            cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(MASTER_KEY, "AES"), spec);
            // AAD binding uses displayName instead of username for profile-bound records
            cipher.updateAAD(displayName.getBytes(StandardCharsets.UTF_8));
            byte[] encrypted = cipher.doFinal(role.getBytes(StandardCharsets.UTF_8));
            byte[] ciphertext = Arrays.copyOfRange(encrypted, 0, encrypted.length - 16);
            byte[] authTag = Arrays.copyOfRange(encrypted, encrypted.length - 16, encrypted.length);
            users.put(username, new UserRecord(username, ciphertext, iv, authTag));
        } catch (Exception e) { throw new RuntimeException(e); }
    }

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/login", exchange -> {
            String user = exchange.getRequestHeaders().getFirst("X-Username");
            String token = createSession(user);
            if (token != null) {
                exchange.sendResponseHeaders(200, token.length());
                exchange.getResponseBody().write(token.getBytes());
            } else { exchange.sendResponseHeaders(401, 0); }
            exchange.getResponseBody().close();
        });
        server.createContext("/register", exchange -> {
            String user = exchange.getRequestHeaders().getFirst("X-Username");
            String role = exchange.getRequestHeaders().getFirst("X-Role");
            boolean ok = registerUser(user, role != null ? role : "ROLE_USER");
            exchange.sendResponseHeaders(ok ? 201 : 409, 0);
            exchange.getResponseBody().close();
        });
        server.createContext("/promote", exchange -> {
            String token = exchange.getRequestHeaders().getFirst("Authorization");
            String target = exchange.getRequestHeaders().getFirst("X-Target");
            boolean ok = promoteUser(token, target);
            exchange.sendResponseHeaders(ok ? 200 : 403, 0);
            exchange.getResponseBody().close();
        });
        server.createContext("/profile", exchange -> {
            String token = exchange.getRequestHeaders().getFirst("Authorization");
            String displayName = exchange.getRequestHeaders().getFirst("X-DisplayName");
            boolean ok = updateProfile(token, displayName);
            exchange.sendResponseHeaders(ok ? 200 : 403, 0);
            exchange.getResponseBody().close();
        });
        server.start();
    }
}
